 <main class="layout"><section class="scene-card"><div class="scene-head"><div class="location"><span class="pin">⌖</span><div><div class="location-name">Willowbrook Farm</div><div class="location-sub">Your little patch of paradise</div></div></div><div class="season-pill"><span id="seasonIcon">🌷</span><span id="seasonName">Spring</span></div></div><div class="canvas-wrap"><canvas id="farm" aria-label="Your nine-plot farm. Click a plot to use your selected tool." tabindex="0"></canvas><div class="scene-hint" id="hint">Pick a tool, then tap a plot ✨</div></div><div class="scene-bottom"><div class="weather"><span class="weather-icon" id="weatherIcon">🌤️</span><div class="weather-copy"><span id="weatherTitle">A gentle spring day</span><small id="weatherSub">Perfect for tending your garden</small></div></div><div class="tool-note" id="toolNote">Choose a tool to get started</div></div></section>
