import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
try {
  const page = await browser.newPage({ viewport: { width: 1200, height: 900 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  const response = await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
  await page.evaluate(() => document.fonts.ready);
  await page.locator('#settingsBtn').click();
  await page.locator('#artStyle').waitFor({ state: 'visible' });
  await page.screenshot({ path: 'screenshots/options-latest.jpg', type: 'jpeg', quality: 78, fullPage: false });
  await page.locator('#artStyle').selectOption('storybook');
  if (await page.locator('body').evaluate(el => el.classList.contains('pixel-art'))) throw new Error('Storybook style did not apply');
  await page.locator('#seasonLength').selectOption('14');
  await page.locator('#reduceMotion').check();
  const persisted = await page.evaluate(() => JSON.parse(localStorage.getItem('littleAcreSave')).options);
  if (persisted.art !== 'storybook' || persisted.seasonLength !== 14 || !persisted.reduceMotion) throw new Error('Options were not saved');
  console.log(JSON.stringify({ status: response.status(), width: 1200, optionsVisible: true, controlsPersist: true, pageErrors: errors }));
} finally { await browser.close(); }
